int register_genl_family(struct genl_family *family) {
    int err = 0;

    if (!family) {
        return -EINVAL;
    }

    if (family->version <= 0 || family->maxattr < 0) {
        return -EINVAL;
    }

    if (family->ops && family->n_ops > 0) {
        for (int i = 0; i < family->n_ops; i++) {
            if (!family->ops[i].cmd || family->ops[i].cmd <= 0) {
                return -EINVAL;
            }
            if (!family->ops[i].doit && !family->ops[i].dumpit) {
                return -EINVAL;
            }
        }
    }

    if (family->id >= GENL_ID_MIN && family->id <= GENL_ID_MAX) {
        return -EINVAL;
    }

    for (int i = 0; i < GENL_ID_MAX; i++) {
        if (genl_families[i] && strcmp(genl_families[i]->name, family->name) == 0) {
            return -EEXIST;
        }
    }

    if (family->mcgrps && family->n_mcgrps > 0) {
        for (int i = 0; i < family->n_mcgrps; i++) {
            if (!family->mcgrps[i].name || strlen(family->mcgrps[i].name) == 0) {
                return -EINVAL;
            }
            if (family->mcgrps[i].maxattr < 0) {
                return -EINVAL;
            }
        }
    }

    if (family->id == 0) {
        for (int i = GENL_ID_MIN; i <= GENL_ID_MAX; i++) {
            if (!genl_families[i]) {
                family->id = i;
                break;
            }
        }
        if (family->id == 0) {
            return -ENOSPC;
        }
    }

    genl_families[family->id] = family;

    return 0;
}
